'use strict';

// MODULES //

var createMatrix = require( './create_matrix.js' );


// MAIN //

/**
* Stores a dense matrix in a strided buffer such that applying a transpose operation to the stored matrix yields the dense matrix.
*
* ## Notes
*
* -   When `trans` equals `'transpose'`, the function stores the `cols×rows` matrix `X^T`, such that `op(stored) = X`.
*
* @private
* @param {Collection} X - dense matrix stored in row-major order
* @param {NonNegativeInteger} rows - number of rows in `X`
* @param {NonNegativeInteger} cols - number of columns in `X`
* @param {string} trans - transpose operation (either `'no-transpose'` or `'transpose'`)
* @param {Object} opts - layout options (see `create_matrix.js`)
* @param {number} fill - value assigned to buffer elements which do not belong to the stored matrix
* @returns {Object} matrix description
*/
function storeMatrix( X, rows, cols, trans, opts, fill ) {
	if ( trans === 'no-transpose' ) {
		return createMatrix( rows, cols, opts, value );
	}
	return createMatrix( cols, rows, opts, transposed );

	/**
	* Returns the value of a stored element when the stored matrix equals `X`.
	*
	* @private
	* @param {integer} i - row index (or `-1` for elements which do not belong to the stored matrix)
	* @param {integer} j - column index
	* @returns {number} element value
	*/
	function value( i, j ) {
		if ( i < 0 ) {
			return fill;
		}
		return X[ ( i*cols )+j ];
	}

	/**
	* Returns the value of a stored element when the stored matrix equals `X^T`.
	*
	* @private
	* @param {integer} i - row index (or `-1` for elements which do not belong to the stored matrix)
	* @param {integer} j - column index
	* @returns {number} element value
	*/
	function transposed( i, j ) {
		if ( i < 0 ) {
			return fill;
		}
		return X[ ( j*cols )+i ];
	}
}


// EXPORTS //

module.exports = storeMatrix;
